var Q28 = [
{n:1, q:'Las misiones de las Fuerzas y Cuerpos de Seguridad se encuentran reguladas:', o:{a:'En el art.104.1 de la Constitución Española.',b:'En el art.104.2 de la Constitución Española.',c:'En el art.53 de la Ley Orgánica 2/86, de Fuerzas y Cuerpos de Seguridad.',d:'En el art.52 de la Ley Orgánica 2/86, de Fuerzas y Cuerpos de Seguridad.'}, correct:'a', why:{a:'El art. 104.1 CE establece que las Fuerzas y Cuerpos de Seguridad, bajo la dependencia del Gobierno, tienen como misión proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana.'}},
{n:2, q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad está estructurada en...', o:{a:'Tres Títulos.',b:'Cinco Títulos.',c:'Cuatro Títulos.',d:'Seis Títulos.'}, correct:'b', why:{b:'La LO 2/1986 se estructura en cinco Títulos: I (Disposiciones Generales), II (Principios básicos de actuación), III (De las FFCCSS del Estado), IV (Policías de las CCAA) y V (De las Policías Locales).'}},
{n:3, q:'El Título I de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad se denomina...', o:{a:'Disposiciones Generales.',b:'Principios básicos de actuación.',c:'De los Cuerpos y Fuerzas de Seguridad.',d:'De los Cuerpos y Fuerzas de Seguridad del Estado.'}, correct:'c', why:{c:'El Título I de la LO 2/1986 se denomina "De los Cuerpos y Fuerzas de Seguridad" y recoge el marco general sobre seguridad pública y las fuerzas que la ejercen.'}},
{n:4, q:'El Título I de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad se estructura en...', o:{a:'Tres capítulos.',b:'Cuatro capítulos.',c:'Cinco capítulos.',d:'Dos capítulos.'}, correct:'a', why:{a:'El Título I de la LO 2/1986 se divide en tres capítulos: Cap. I (De la seguridad pública), Cap. II (Principios básicos de actuación) y Cap. III (Disposiciones estatutarias comunes).'}},
{n:5, q:'El Capítulo I del Título I de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad...', o:{a:'Se denomina "De las Fuerzas y Cuerpos de Seguridad".',b:'Comprende los artículos 1 a 5.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El Cap. I del Título I se denomina "De la seguridad pública" (no "De las Fuerzas y Cuerpos de Seguridad") y comprende los arts. 1 a 3 (no 1 a 5), por lo que ambas afirmaciones son incorrectas.'}},
{n:6, q:'El Capítulo II del Título I de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad se denomina...', o:{a:'Disposiciones estatutarias comunes.',b:'Principios básicos de actuación.',c:'Disposiciones generales.',d:'Del Consejo de Policía.'}, correct:'b', why:{b:'El Cap. II del Título I de la LO 2/1986 lleva por rúbrica "Principios básicos de actuación" y recoge el art. 5, que enumera todos los principios que deben regir la actuación de los miembros de las FFCCSS.'}},
{n:7, q:'El Capítulo III del Título I de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad se denomina...', o:{a:'Disposiciones estatutarias comunes.',b:'Disposiciones generales.',c:'Del Consejo de Policía.',d:'Principios básicos de actuación.'}, correct:'a', why:{a:'El Cap. III del Título I de la LO 2/1986 se denomina "Disposiciones estatutarias comunes", recogiendo en los arts. 6, 7 y 8 los derechos y obligaciones comunes a todos los miembros de las FFCCSS.'}},
{n:8, q:'El Capítulo III del Título I de la Ley Orgánica 2/1986 comprende los artículos...', o:{a:'5, 6, 7 y 8.',b:'5, 6 y 7.',c:'6, 7 y 8.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El Cap. III del Título I (Disposiciones estatutarias comunes) comprende los arts. 6, 7 y 8 de la LO 2/1986, que regulan promoción profesional, derechos sindicales, carácter de agentes de autoridad y régimen disciplinario.'}},
{n:9, q:'El Capítulo II del Título I de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad comprende los artículos...', o:{a:'5, 6, 7 y 8.',b:'5, 6 y 7.',c:'6, 7 y 8.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El Cap. II del Título I (Principios básicos de actuación) comprende exclusivamente el art. 5. Los arts. 6, 7 y 8 pertenecen al Cap. III. Por tanto, ninguna de las opciones anteriores es correcta.'}},
{n:10, q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad establece...', o:{a:'Que la seguridad pública es competencia exclusiva del Estado, susceptible de ser compartida con las Comunidades Autónomas.',b:'Que la seguridad pública es competencia exclusiva del Estado y que su mantenimiento corresponde al Gobierno de la Nación.',c:'Que el mantenimiento de la seguridad pública se ejercerá por el Ministerio del Interior.',d:'Que las CCAA y Corporaciones Locales pueden ejercer competencias en materia de seguridad pública, en los términos que determine una Ley Orgánica.'}, correct:'b', why:{b:'El art. 1 LO 2/1986 dispone que la seguridad pública es competencia exclusiva del Estado y que su mantenimiento corresponde al Gobierno de la Nación.'}},
{n:11, q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad establece...', o:{a:'Que las corporaciones locales participarán en el mantenimiento de la seguridad pública en los términos establecidos en la Ley de Bases de Régimen Local y en el marco de la legislación de la respectiva Comunidad Autónoma.',b:'Que las CCAA participarán en el mantenimiento de la seguridad pública en los términos que establezcan los respectivos Estatutos y en el marco de esta Ley.',c:'Que el mantenimiento de la seguridad pública se ejercerá exclusivamente por la Administración del Estado, a través de las FFCCSS del Estado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 2.2 LO 2/1986 establece que las CCAA participarán en el mantenimiento de la seguridad pública en los términos que establezcan los respectivos Estatutos y en el marco de esta Ley.'}},
{n:12, q:'La Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad dispone que corresponde a las Comunidades Autónomas...', o:{a:'Regular las funciones de las Policías Locales en su ámbito territorial.',b:'Coordinar la actuación de las Policías Locales en su ámbito territorial.',c:'Regular las competencias de las Policías Locales de su ámbito territorial.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 39.1 LO 2/1986 atribuye a las CCAA la competencia de coordinar la actuación de las Policías Locales en el ámbito territorial de la Comunidad Autónoma.'}},
{n:13, q:'Según la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad, son Fuerzas y Cuerpos de Seguridad...', o:{a:'Los Cuerpos de Policía dependientes de las Comunidades Autónomas.',b:'Los Cuerpos de Policía dependientes de las Corporaciones Locales.',c:'Las Fuerzas y Cuerpos de Seguridad del Estado dependientes del Gobierno de la Nación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 2 LO 2/1986 enumera como FFCCSS: las del Estado (Guardia Civil y CNP), las dependientes de las CCAA y los Cuerpos de Policía de las Corporaciones Locales (Policías Locales).'}},
{n:14, q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad establece que la seguridad pública se ejercerá...', o:{a:'Por todas las FFCCSS, en los términos que establezca una Ley Orgánica.',b:'Por las distintas administraciones públicas a través de las Fuerzas y Cuerpos de Seguridad.',c:'Por las distintas administraciones en los términos que establezca una Ley Orgánica.',d:'Por las distintas administraciones públicas a través de las FFCCSS del Estado.'}, correct:'b', why:{b:'El art. 1.2 LO 2/1986 dispone que el mantenimiento de la seguridad pública se ejercerá por las distintas Administraciones Públicas a través de las Fuerzas y Cuerpos de Seguridad.'}},
{n:15, q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad establece que los miembros de estos Cuerpos y Fuerzas ajustarán su actuación:', o:{a:'Al principio de cooperación recíproca.',b:'Al principio de mínima intervención.',c:'Al principio de territorialidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 5.1 LO 2/1986 recoge entre los principios básicos de actuación el de cooperación recíproca y coordinación, que implica que los miembros de las FFCCSS deben actuar en colaboración con otras instituciones.'}},
{n:16, q:'Según el art.4 de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, el deber de prestar a las FFCCSS el auxilio necesario en la investigación y persecución de los delitos, corresponde a...', o:{a:'Las respectivas administraciones públicas.',b:'Todos los funcionarios y autoridades.',c:'Los miembros del Poder Judicial.',d:'Todos.'}, correct:'d', why:{d:'El art. 4 LO 2/1986 impone a todos (ciudadanos, autoridades, entidades públicas y privadas) la obligación de prestar a las FFCCSS la colaboración requerida para la investigación y persecución de delitos.'}},
{n:17, q:'La Ley Orgánica 2/1986 atribuye una especial obligación de auxiliar o colaborar en todo momento con las Fuerzas y Cuerpos de Seguridad:', o:{a:'A las personas y entidades que ejerzan funciones de vigilancia, seguridad o custodia referidas a personal y bienes de servicios de titularidad pública.',b:'A las personas y entidades que ejerzan funciones de vigilancia, seguridad o custodia referidas a personal y bienes de servicios de titularidad privada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 4 LO 2/1986 impone especial obligación de colaboración tanto a los vigilantes de servicios de titularidad pública como privada, abarcando ambos supuestos.'}},
{n:18, q:'Los principios básicos de actuación de los integrantes de las Fuerzas y Cuerpos de Seguridad están recogidos:', o:{a:'En los artículos cuarto, quinto y sexto de la Ley Orgánica 2/1986.',b:'En el artículo cuarto de la Ley Orgánica 2/1986.',c:'En los artículos quinto y sexto de la Ley Orgánica 2/1986.',d:'En el artículo quinto de la Ley Orgánica 2/1986.'}, correct:'d', why:{d:'Los principios básicos de actuación están recogidos íntegramente en el art. 5 de la LO 2/1986, que enumera los principios de adecuación al ordenamiento jurídico, secreto profesional, responsabilidad y relaciones con la comunidad.'}},
{n:19, q:'De acuerdo con lo establecido en el artículo 5 de la Ley Orgánica 2/1986 es un principio básico de actuación de los miembros de las Fuerzas y Cuerpos de Seguridad:', o:{a:'La dedicación profesional.',b:'El secreto profesional.',c:'La responsabilidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 5 LO 2/1986 recoge como principios básicos de actuación la dedicación profesional (art. 5.1.b), el secreto profesional (art. 5.1.f) y la responsabilidad (art. 5.1.h), entre otros.'}},
{n:20, q:'El principio de "adecuación al ordenamiento jurídico", exigido por la Ley Orgánica 2/1986 a los miembros de las FFCCSS, implica que éstos, especialmente, deben:', o:{a:'Ejercer su función con absoluto respeto a la Constitución y al resto del ordenamiento jurídico.',b:'Llevar a cabo sus funciones con total dedicación.',c:'Velar por la vida e integridad de las personas a quienes detuvieren.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 5.1.a) LO 2/1986 establece que la adecuación al ordenamiento jurídico implica ejercer la función con absoluto respeto a la Constitución y al resto del ordenamiento jurídico.'}},
{n:21, q:'El principio de "adecuación al ordenamiento jurídico", exigido por la Ley Orgánica 2/1986 a los miembros de las FFCCSS, implica que éstos, especialmente, deben:', o:{a:'Impedir en el ejercicio de su actuación profesional cualquier práctica abusiva, arbitraria o discriminatoria.',b:'Actuar con integridad y dignidad; y en particular, deberán abstenerse de todo acto de corrupción y oponerse a él resueltamente.',c:'Observar en todo momento un trato correcto y esmerado con los ciudadanos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 5.1.b) LO 2/1986 incluye dentro de la adecuación al ordenamiento jurídico actuar con integridad y dignidad, y abstenerse de todo acto de corrupción oponiéndose a él resueltamente.'}},
{n:22, q:'El principio de "adecuación al ordenamiento jurídico", exigido por la Ley Orgánica 2/1986 a los miembros de las FFCCSS, implica que éstos, especialmente, deben:', o:{a:'Guardar riguroso secreto, respecto a todas las informaciones que conozcan por razón, o con ocasión del desempeño de sus funciones.',b:'Impedir, en el ejercicio de su actuación profesional, cualquier práctica abusiva, arbitraria o discriminatoria, que entrañe violencia física o moral.',c:'Velar por la vida e integridad física de las personas que se hallen bajo su custodia, respetando el honor y la dignidad de éstas.',d:'Actuar, en el cumplimiento de sus funciones, con absoluta neutralidad política e imparcialidad y, en consecuencia, sin discriminación alguna por razón de raza, sexo, religión u opinión.'}, correct:'d', why:{d:'El art. 5.1.d) LO 2/1986 exige, dentro del principio de adecuación al ordenamiento jurídico, actuar con absoluta neutralidad política e imparcialidad, sin discriminación por razón de raza, sexo, religión u opinión.'}},
{n:23, q:'El principio de "adecuación al ordenamiento jurídico", exigido por la Ley Orgánica 2/1986 a los miembros de las FFCCSS, implica que éstos, especialmente, deben:', o:{a:'Sujetarse a los principios de jerarquía y subordinación sin que, en ningún caso, la obediencia debida pueda amparar órdenes que entrañen la ejecución de actos que manifiestamente constituyan delito o sean contrarios a la constitución o las leyes.',b:'Colaborar con la Administración de Justicia y auxiliarla en los términos establecidos en la ley.',c:'Las respuestas a y b con correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 5.1 LO 2/1986 incluye tanto la sujeción a jerarquía sin amparar órdenes delictivas (art. 5.1.a) como la colaboración con la Administración de Justicia (art. 5.1.c), siendo ambas parte del principio de adecuación al ordenamiento.'}},
{n:24, q:'El principio de "relaciones con la comunidad", exigido por la Ley Orgánica 2/1986 a los miembros de las FFCCSS, implica que éstos, singularmente, deben:', o:{a:'Observar en todo momento un trato correcto y esmerado con los ciudadanos, a quienes procurarán auxiliar y proteger, siempre que las circunstancias lo aconsejen o fueren requeridos para ello al tiempo que facilitarán toda la información posible sobre las causas y finalidad de sus intervenciones.',b:'Actuar con integridad y dignidad y, en particular, deberán abstenerse de todo acto de corrupción y oponerse a él resueltamente.',c:'Identificarse debidamente como tales en el momento de efectuar una detención.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 5.2.a) LO 2/1986 establece que el principio de relaciones con la comunidad implica dispensar un trato correcto y esmerado, auxiliar y proteger a los ciudadanos cuando sea necesario, y facilitarles información sobre las causas y finalidad de las intervenciones.'}},
{n:25, q:'El principio de "relaciones con la comunidad", exigido por la Ley Orgánica 2/1986 a los miembros de las FFCCSS, implica que éstos, singularmente, deben:', o:{a:'Llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, en defensa de la Ley y de la seguridad ciudadana.',b:'En el ejercicio de sus funciones, actuar con la decisión necesaria y sin demora cuando de ello dependa evitar un daño grave, inmediato e irreparable, rigiendo su actuación por los principios de congruencia, oportunidad y proporcionalidad en la utilización de los medios a su alcance.',c:'Colaborar con la administración de justicia y auxiliarla en los términos establecidos en la Ley.',d:'Identificarse debidamente como tales, en el momento de efectuar una detención.'}, correct:'b', why:{b:'El art. 5.2.b) LO 2/1986 establece que las relaciones con la comunidad exigen actuar con la decisión necesaria y sin demora para evitar daños graves, bajo los principios de congruencia, oportunidad y proporcionalidad.'}},
{n:26, q:'El principio de "relaciones con la comunidad", exigido por la Ley Orgánica 2/1986 a los miembros de las FFCCSS, implica que éstos, singularmente, deben:', o:{a:'Impedir, en el ejercicio de sus funciones, cualquier práctica abusiva, arbitraria o discriminatoria.',b:'En todas sus intervenciones, proporcionar información cumplida, y tan amplia como sea posible, sobre las causas y finalidad de las mismas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 5.2 LO 2/1986 incluye en el principio de relaciones con la comunidad tanto impedir prácticas abusivas como proporcionar información amplia sobre causas y finalidad de las intervenciones.'}},
{n:27, q:'Según el artículo 5.2 de la Ley Orgánica 2/1986, los miembros de estos colectivos deberán auxiliar y proteger a los ciudadanos...', o:{a:'En todo momento y lugar, en defensa de la Ley y de la seguridad ciudadana.',b:'De acuerdo con los principios de congruencia, oportunidad y proporcionalidad, en la utilización de los medios a su alcance.',c:'Siempre que las circunstancias lo aconsejen o fueren requeridos para ello.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 5.2.a) LO 2/1986 establece que los miembros de las FFCCSS procurarán auxiliar y proteger a los ciudadanos "siempre que las circunstancias lo aconsejen o fueren requeridos para ello".'}},
{n:28, q:'Conforme a lo previsto en el artículo 5.2 de la Ley Orgánica 2/1986, y con respecto al uso de las armas, los miembros de las FFCCSS deben tener en cuenta el principio de:', o:{a:'Lesividad.',b:'Obediencia debida.',c:'Proporcionalidad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 5.2.c) LO 2/1986 exige, en el uso de armas, el principio de proporcionalidad: solo se usarán cuando exista riesgo grave para la vida o integridad física, y de forma proporcionada a la amenaza.'}},
{n:29, q:'Conforme a lo previsto en el artículo 5.2 de la Ley Orgánica 2/1986, y con respecto al uso de las armas, los miembros de las FFCCSS deberán tener en cuenta:', o:{a:'El principio de congruencia.',b:'El principio de oportunidad.',c:'El principio de proporcionalidad.',d:'Todos los principios citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 5.2.c) LO 2/1986 exige para el uso de armas la observancia conjunta de los principios de congruencia, oportunidad y proporcionalidad.'}},
{n:30, q:'Con respecto al uso de las armas por parte de los miembros de las FFCCSS, el principio de proporcionalidad:', o:{a:'Obliga a utilizar idénticos medios lesivos que los que utilice el agresor.',b:'Se aplica en casos excepcionales recogidos en una norma con rango de ley.',c:'Impide responder a una agresión con armas de superior efecto lesivo que las utilizadas por el agresor.',d:'Impide actuar antes de que se produzca la agresión.'}, correct:'c', why:{c:'El principio de proporcionalidad en el uso de armas (art. 5.2.c LO 2/1986) veda responder con medios de mayor efecto lesivo del estrictamente necesario, lo que incluye no utilizar armas de superior potencia a las del agresor salvo necesidad justificada.'}},
{n:31, q:'Conforme a lo previsto en el artículo 5.2 de la Ley Orgánica 2/1986, los miembros de las FFCCSS solamente deberán utilizar las armas...', o:{a:'En situaciones en que exista un riesgo grave para su vida.',b:'En aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana.',c:'En situaciones en que exista un riesgo grave para su integridad física o la de terceras personas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 5.2.c) LO 2/1986 solo permite el uso de armas cuando exista riesgo grave para la vida o integridad física propias o de terceros, o cuando la situación pueda suponer grave riesgo para la seguridad ciudadana.'}},
{n:32, q:'En los principios básicos referidos al tratamiento de detenidos de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, se proclama', o:{a:'La obligación de identificarse debidamente en el momento de efectuar una detención.',b:'La obligación de utilizar las armas, solamente, en situaciones de riesgo racionalmente grave para la vida o integridad física del policía, o la de terceras personas.',c:'La obligación de impedir, en el ejercicio de la actuación policial, cualquier práctica abusiva, arbitraria o discriminatoria, que entrañe violencia física o moral.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 5.3 LO 2/1986, sobre el trato a los detenidos, incluye expresamente la obligación de identificarse debidamente como miembro de las FFCCSS en el momento de efectuar una detención.'}},
{n:33, q:'Conforme a lo previsto en la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, los miembros de estos colectivos...', o:{a:'Velarán por la vida e integridad física de las personas a quienes detuvieren o que se encuentren bajo su custodia y respetarán el honor y la dignidad de éstas.',b:'Darán cumplimiento y observarán con la debida diligencia, los trámites, plazos y requisitos exigidos por el ordenamiento jurídico, cuando se proceda a la detención de una persona.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 5.3 LO 2/1986 establece ambas obligaciones en el trato a detenidos: velar por su vida e integridad y respetar su honor, así como cumplir diligentemente los trámites exigidos por el ordenamiento en la detención.'}},
{n:34, q:'El principio de "dedicación profesional", exigido por la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, implica que los integrantes de estos colectivos...', o:{a:'Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir dentro del ámbito de sus respectivas funciones, cuando se encuentren de servicio en defensa de la ley y de la seguridad ciudadana.',b:'Deberán llevar a cabo sus funciones con dedicación exclusiva, debiendo intervenir siempre dentro del ámbito de sus respectivas funciones y proteger a los ciudadanos, en defensa de la ley y de la seguridad ciudadana.',c:'Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre que fuesen requeridos para ello, en cualquier momento y lugar, y en el ámbito de sus respectivas competencias, en defensa de la ley y de la seguridad ciudadana.',d:'Deberán llevar a cabo sus funciones con total dedicación, debiendo intervenir siempre en cualquier tiempo y lugar, se hallaren o no de servicio, en defensa de la ley y de la seguridad ciudadana.'}, correct:'d', why:{d:'El art. 5.1.b) LO 2/1986 establece que la dedicación profesional implica llevar a cabo las funciones con total dedicación, debiendo intervenir siempre, en cualquier tiempo y lugar, se hallen o no de servicio, en defensa de la ley y la seguridad ciudadana.'}},
{n:35, q:'El principio de secreto profesional, exigido por la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, implica que los integrantes de estos colectivos...', o:{a:'Deberán guardar riguroso secreto respecto a todas las informaciones que conozcan por razón o con ocasión del desempeño de sus funciones.',b:'No estarán obligados a revelar las fuentes de información, salvo que el ejercicio de sus funciones o las disposiciones de la ley les impongan actuar de otra manera.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 5.1.f) LO 2/1986 establece que el secreto profesional implica que los miembros de las FFCCSS no estarán obligados a revelar las fuentes de información, salvo que el ejercicio de sus funciones o la ley les impongan actuar de otra manera.'}},
{n:36, q:'El principio de responsabilidad establecido en la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, implica que los integrantes de estos colectivos son responsables personal y directamente:', o:{a:'De los actos que en su actuación profesional lleven a cabo infringiendo o vulnerando las normas legales.',b:'De los actos que en su actuación profesional lleven a cabo infringiendo o vulnerando las normas reglamentarias que rijan su profesión.',c:'De los actos que en su actuación profesional lleven a cabo infringiendo o vulnerando los principios básicos de actuación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 5.1.h) LO 2/1986 establece que los miembros de las FFCCSS son personalmente responsables de los actos contrarios a las normas legales, reglamentarias y a los propios principios básicos de actuación.'}},
{n:37, q:'El principio de responsabilidad establecido en la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, implica que los integrantes de estos colectivos son responsables personal y directamente por los actos que en su actuación profesional lleven a cabo, sin perjuicio de...', o:{a:'La responsabilidad penal que pueda corresponder a las Administraciones Públicas por esta causa.',b:'La responsabilidad patrimonial que pueda corresponder a las Administraciones Públicas por esta causa.',c:'La responsabilidad civil que pueda corresponder a las Administraciones Públicas por esta causa.',d:'La responsabilidad administrativa que pueda corresponder a las Administraciones Públicas por esta causa.'}, correct:'b', why:{b:'El art. 5.1.h) LO 2/1986 dispone que la responsabilidad personal de los miembros de las FFCCSS es sin perjuicio de la responsabilidad patrimonial que pueda corresponder a las Administraciones Públicas.'}},
{n:38, q:'Las disposiciones estatutarias comunes a todas las Fuerzas y Cuerpos de Seguridad están recogidas en...', o:{a:'El capítulo III del Título I de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.',b:'El capítulo II del Título I de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.',c:'El capítulo III del Título II de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.',d:'El capítulo II del Título II de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.'}, correct:'a', why:{a:'Las disposiciones estatutarias comunes están en el Capítulo III del Título I de la LO 2/1986 (arts. 6, 7 y 8), que regula la promoción profesional, los derechos sindicales, el carácter de agentes de autoridad y el régimen disciplinario.'}},
{n:39, q:'Las disposiciones estatutarias comunes a todas las Fuerzas y Cuerpos de Seguridad están recogidas en...', o:{a:'Los artículos quinto, sexto y séptimo de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.',b:'Los artículos sexto, séptimo y octavo de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.',c:'Los artículos séptimo, octavo y noveno de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.',d:'Los artículos cuarto, quinto y sexto de la Ley Orgánica 2/86 de Fuerzas y Cuerpos de Seguridad.'}, correct:'b', why:{b:'Las disposiciones estatutarias comunes se encuentran en los arts. 6, 7 y 8 de la LO 2/1986 (Cap. III, Título I), que contienen las normas comunes sobre promoción, derechos, responsabilidad y régimen disciplinario de todos los miembros de las FFCCSS.'}},
{n:40, q:'La Ley Orgánica 2/1986 establece, con respecto a los miembros de las FFCCSS, que los poderes públicos promoverán las condiciones mas favorables para una adecuada...', o:{a:'Promoción profesional.',b:'Promoción social.',c:'Promoción humana.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 6.1 LO 2/1986 establece que los poderes públicos promoverán las condiciones más favorables para la adecuada promoción profesional, social y humana de los miembros de las FFCCSS.'}},
{n:41, q:'Indique la respuesta correcta. La Ley Orgánica 2/1986 establece que los poderes públicos promoverán las condiciones más favorables para una adecuada promoción profesional, social y humana de los miembros de las FFCCSS, de acuerdo con los principios de:', o:{a:'Responsabilidad.',b:'Igualdad de trato con respecto al resto de funcionarios públicos.',c:'Objetividad.',d:'Estabilidad.'}, correct:'c', why:{c:'El art. 6.1 LO 2/1986 recoge la objetividad como uno de los principios rectores de la promoción profesional, social y humana de los miembros de las FFCCSS.'}},
{n:42, q:'Indique la respuesta correcta. La Ley Orgánica 2/1986 establece que los poderes públicos promoverán las condiciones más favorables para una adecuada promoción profesional, social y humana de los miembros de las FFCCSS, de acuerdo con los principios de:', o:{a:'Igualdad de oportunidades.',b:'Profesionalidad.',c:'Justicia social.',d:'Asignación de funciones.'}, correct:'a', why:{a:'El art. 6.1 LO 2/1986 recoge la igualdad de oportunidades como principio rector de la promoción de los miembros de las FFCCSS.'}},
{n:43, q:'Indique la respuesta correcta. La Ley Orgánica 2/1986 establece que los poderes públicos promoverán las condiciones más favorables para una adecuada promoción profesional, social y humana de los miembros de las FFCCSS, de acuerdo con los principios de:', o:{a:'Dedicación.',b:'Mérito y capacidad.',c:'Riesgo que comporta su misión.',d:'Movilidad por razones de servicio.'}, correct:'a', why:{a:'El art. 6.1 LO 2/1986 recoge la dedicación como uno de los principios de la adecuada promoción profesional de los miembros de las FFCCSS.'}},
{n:44, q:'Para una adecuada promoción social, profesional y humana de los integrantes de las FFCCSS, la Ley Orgánica 2/1986 obliga a los poderes públicos a:', o:{a:'Remover los obstáculos que impidan el logro de este objetivo.',b:'Promover las condiciones más favorables para lograr este objetivo.',c:'Llevar a cabo cuantos estudios se precisen para que este derecho sea real y efectivo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 6.1 LO 2/1986 obliga a los poderes públicos a promover las condiciones más favorables para lograr la efectiva promoción profesional, social y humana de los integrantes de las FFCCSS.'}},
{n:45, q:'Con respecto a la formación de los miembros de las FFCCSS, la Ley Orgánica 2/1986 exige:', o:{a:'Que ésta tenga carácter profesional y permanente.',b:'Que puedan ser objeto de convalidación los estudios que se cursen en los centros de enseñanza de las diferentes administraciones públicas.',c:'Que para convalidar los estudios que realicen los integrantes de estos Cuerpos, el Ministerio tenga en cuenta las titulaciones exigidas para el acceso a cada uno de ellos, y la naturaleza y duración de los mismos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 6 LO 2/1986 en sus apartados 2 y 3 establece que la formación tendrá carácter profesional y permanente, los estudios son convalidables y se considerarán las titulaciones exigidas y duración de los mismos.'}},
{n:46, q:'Con respecto a la formación de los miembros de las FFCCSS, la Ley Orgánica 2/1986 dispone que para impartir las distintas enseñanzas y cursos se promoverá la colaboración institucional de:', o:{a:'La Universidad.',b:'La Administración del Estado.',c:'Las Comunidades Autónomas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 6.4 LO 2/1986 dispone que para impartir enseñanzas y cursos de formación se promoverá especialmente la colaboración institucional de la Universidad.'}},
{n:47, q:'Con respecto a la formación de los miembros de las FFCCSS, la Ley Orgánica 2/1986 dispone que para impartir las distintas enseñanzas y cursos se promoverá la colaboración institucional de:', o:{a:'El Ministerio Fiscal.',b:'El Poder Judicial.',c:'Las Fuerzas Armadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 6.4 LO 2/1986 prevé la colaboración institucional del Ministerio Fiscal, el Poder Judicial y las Fuerzas Armadas, entre otros, para la impartición de enseñanzas y cursos de formación.'}},
{n:48, q:'Según lo dispuesto en las Disposiciones Estatutarias Comunes de la Ley Orgánica 2/1986, los miembros de las Fuerzas y Cuerpos de Seguridad...', o:{a:'Deben jurar o prometer acatamiento a la Constitución y al resto del ordenamiento jurídico.',b:'Tienen derecho a una remuneración justa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 7 LO 2/1986 establece ambas: la obligación de jurar o prometer acatamiento a la Constitución y el derecho a una remuneración justa que contemple las especificidades de la función.'}},
{n:49, q:'La Ley Orgánica 2/1986 establece que los miembros de las Fuerzas y Cuerpos de Seguridad...', o:{a:'No podrán ejercer en ningún caso el derecho de huelga.',b:'En el ejercicio de sus funciones tienen, a todos los efectos legales, el carácter de agentes de la autoridad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 7 LO 2/1986 establece que los miembros de las FFCCSS no pueden ejercer el derecho de huelga (art. 6.7) y que en el ejercicio de sus funciones tienen el carácter de agentes de la autoridad (art. 7.1).'}},
{n:50, q:'El artículo 6 Ley Orgánica 2/1986 establece que los miembros de las Fuerzas y Cuerpos de Seguridad...', o:{a:'No podrán ejercer, en ningún caso, acciones concertadas con el fin de alterar el normal funcionamiento de los servicios.',b:'Tienen derecho a que los puestos de servicio en las respectivas categorías se provean de acuerdo con los principios de publicidad, antigüedad, mérito y capacidad, en los términos que establezca la ley.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 6.7 LO 2/1986 establece que los miembros de las FFCCSS no podrán ejercer, en ningún caso, acciones concertadas con el fin de alterar el normal funcionamiento de los servicios.'}},
{n:51, q:'Según el artículo 6.4 de la Ley Orgánica 2/1986, los miembros de las FFCCSS tendrán derecho a una remuneración justa que contemple:', o:{a:'Su nivel de formación.',b:'Su régimen de incompatibilidades.',c:'El riesgo que comporta su misión.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 6.4 LO 2/1986 establece que la remuneración justa contemplará el nivel de formación, el riesgo de la misión y el régimen de incompatibilidades, entre otros factores.'}},
{n:52, q:'Según el artículo 6.4 de la Ley Orgánica 2/1986, los miembros de las FFCCSS tendrán derecho a una remuneración justa que contemple:', o:{a:'La movilidad por razones de servicio.',b:'Las enfermedades profesionales que se produzcan en el ejercicio de sus funciones.',c:'Los servicios extraordinarios que realicen.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 6.4 LO 2/1986 establece que la remuneración justa contemplará, entre otros factores, la movilidad por razones de servicio.'}},
{n:53, q:'Según el artículo 6.4 de la Ley Orgánica 2/1986, los miembros de las FFCCSS tendrán derecho a una remuneración justa que contemple:', o:{a:'La responsabilidad civil derivada de sus actuaciones profesionales',b:'La especificidad de los horarios de trabajo y su peculiar estructura.',c:'Sus circunstancias familiares.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 6.4 LO 2/1986 contempla expresamente la especificidad de los horarios de trabajo y su peculiar estructura como factor de la remuneración justa de los miembros de las FFCCSS.'}},
{n:54, q:'La Ley Orgánica 2/1986, con respecto al régimen de los horarios de servicio de los miembros de las FFCCSS, dispone que:', o:{a:'Se regularán mediante ley y tendrán en cuenta la peculiar estructura de estos Cuerpos.',b:'Se determinarán reglamentariamente y se adaptarán a las peculiares características de la función policial.',c:'Se fijarán en el marco de una ley orgánica, teniendo en cuenta las peculiares características de la función policial y la estructura de estos Cuerpos.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 6.5 LO 2/1986 establece que el régimen de horarios de servicio se determinará reglamentariamente, adaptándose a las peculiares características de la función policial.'}},
{n:55, q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad establece...', o:{a:'Que la pertenencia a estas Fuerzas y Cuerpos es causa de incompatibilidad para el desempeño de cualquier otra actividad pública o privada, salvo aquellas actividades exceptuadas en la legislación sobre incompatibilidades.',b:'Que el régimen disciplinario de los integrantes de estos Cuerpos y Fuerzas estará inspirado en los principios de respeto y consideración, con las debidas garantías.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 6.6 LO 2/1986 establece que la pertenencia a las FFCCSS es causa de incompatibilidad para el desempeño de cualquier otra actividad pública o privada, salvo las exceptuadas en la legislación sobre incompatibilidades.'}},
{n:56, q:'Según el artículo 6 de la Ley Orgánica 2/1986, el régimen disciplinario de los miembros de las FFCCSS:', o:{a:'Tendrá las debidas garantías.',b:'Estará inspirado en unos principios acordes con la misión fundamental que la Constitución Española atribuye a estos Cuerpos y Fuerzas.',c:'Tendrá en cuenta la estructura y organización jerarquizada y disciplinada, propia de estos Cuerpos y Fuerzas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 6.8 LO 2/1986 establece que el régimen disciplinario tendrá las debidas garantías, estará inspirado en la misión constitucional de las FFCCSS y tomará en consideración su estructura jerarquizada y disciplinada.'}},
{n:57, q:'Según el artículo 6.6 de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, los puestos de servicio en las respectivas categorías se proveerán conforme a los principios de:', o:{a:'Objetividad e igualdad de oportunidades.',b:'Mérito, capacidad y antigüedad.',c:'Mérito y capacidad.',d:'Selección y provisión de puestos.'}, correct:'b', why:{b:'El art. 6.6 LO 2/1986 dispone que los puestos de servicio en las respectivas categorías se proveerán conforme a los principios de mérito, capacidad y antigüedad.'}},
{n:58, q:'Según la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, para que los integrantes de estos Cuerpos tengan la consideración de autoridad en los delitos de atentado, se requiere:', o:{a:'Que en la ejecución del delito se empleen armas de fuego, explosivos u otros medios de agresión de análoga peligrosidad.',b:'Que el funcionario contra el que se atenta se halle realizando las funciones propias del cargo.',c:'Que se realice con abuso de función pública.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 7.1 LO 2/1986 establece que para que los miembros de las FFCCSS tengan la consideración de autoridad en los delitos de atentado se requiere que en su ejecución se empleen armas de fuego, explosivos u otros medios de análoga peligrosidad.'}},
{n:59, q:'La pertenencia a las Fuerzas y Cuerpos de Seguridad es causa de incompatibilidad para el desempeño de cualquier otra actividad pública o privada:', o:{a:'Salvo aquellas actividades declaradas de interés general.',b:'Salvo las actividades que tengan relación con la función que tienen encomendada y en el marco de servicios extraordinarios.',c:'Salvo aquellas actividades exceptuadas de la legislación sobre incompatibilidades.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 6.6 LO 2/1986 establece la incompatibilidad con cualquier otra actividad salvo las exceptuadas expresamente en la legislación sobre incompatibilidades.'}},
{n:60, q:'Los miembros de las Fuerzas y Cuerpos de Seguridad:', o:{a:'No podrán ejercer, en ningún caso, el derecho de huelga.',b:'No podrán realizar, en ningún caso, acciones sustitutivas del derecho de huelga.',c:'No podrán realizar, en ningún caso, acciones concertadas con el fin de alterar el normal funcionamiento de los servicios.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 6.7 LO 2/1986 prohíbe a los miembros de las FFCCSS ejercer el derecho de huelga, realizar acciones sustitutivas del mismo y cualquier acción concertada para alterar el funcionamiento normal de los servicios.'}},
{n:61, q:'Según la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, el régimen disciplinario de los integrantes de estos Cuerpos estará inspirado...', o:{a:'En los principios que inspiran el régimen disciplinario de las Fuerzas Armadas.',b:'En unos principios acordes con la misión fundamental que la Constitución les atribuye.',c:'En la difícil misión que esta Ley les asigna, sin perjuicio de los recursos que procedan en el ámbito judicial contencioso administrativo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 6.8 LO 2/1986 establece que el régimen disciplinario estará inspirado en principios acordes con la misión fundamental que la Constitución Española atribuye a los Cuerpos y Fuerzas de Seguridad.'}},
{n:62, q:'Según la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, los miembros de estos Cuerpos y Fuerzas, tienen a todos los efectos legales el carácter de...', o:{a:'Autoridad.',b:'Agentes de la autoridad.',c:'Auxiliares de los agentes de la autoridad.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El art. 7.1 LO 2/1986 establece que los miembros de las FFCCSS tienen, en el ejercicio de sus funciones, el carácter de agentes de la autoridad a todos los efectos legales.'}},
{n:63, q:'Según la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, para que los integrantes de estos Cuerpos tengan la consideración de autoridad en los delitos de atentado, se requiere:', o:{a:'Que en su ejecución se empleen armas de fuego, explosivos, u otros medios de análoga peligrosidad.',b:'Que los medios utilizados para cometer el delito puedan poner en peligro grave la integridad física de los miembros de estos Cuerpos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 7.1 LO 2/1986 exige únicamente el empleo de armas de fuego, explosivos u otros medios de análoga peligrosidad para que los miembros de las FFCCSS tengan la consideración de autoridad en los delitos de atentado.'}},
{n:64, q:'Según la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, la jurisdicción ordinaria es competente para:', o:{a:'Conocer todos los delitos que se cometan contra miembros de las FFCCSS, y contra sus familiares directos, siempre que estos delitos se hayan cometido mientras realizaban sus funciones.',b:'Conocer todos los delitos que se cometan contra quienes tengan la consideración de miembros de las FFCCSS, tengan o no relación con el ejercicio de sus funciones.',c:'Conocer los delitos que cometan los miembros de las FFCCSS en el ejercicio de sus funciones.',d:'Conocer los delitos que cometan los miembros de las FFCCSS, salvo los delitos contra la seguridad del Estado.'}, correct:'d', why:{d:'El art. 7.2 LO 2/1986 establece que la jurisdicción ordinaria es competente para conocer los delitos cometidos por los miembros de las FFCCSS, salvo aquellos que corresponden a la jurisdicción militar conforme a la legislación vigente.'}},
{n:65, q:'De acuerdo con el art.8.2 de la Ley Orgánica 2/1986, el cumplimiento de penas privativas de libertad de los miembros de las FFCCSS se realizará:', o:{a:'En establecimientos penitenciarios ordinarios, dentro de los módulos establecidos al efecto.',b:'En los centros penitenciarios dependientes de la administración militar.',c:'En establecimientos penitenciarios especiales, en los términos regulados en la Ley Orgánica del Poder Judicial.',d:'En establecimientos penitenciarios ordinarios con separación del resto de detenidos o presos.'}, correct:'d', why:{d:'El art. 8.2 LO 2/1986 establece que el cumplimiento de penas privativas de libertad de los miembros de las FFCCSS se realizará en establecimientos penitenciarios ordinarios, con separación del resto de detenidos o presos.'}},
{n:66, q:'Según la Ley Orgánica 2/1986, la iniciación de un procedimiento penal contra miembros de las FFCCSS...', o:{a:'Impedirá la incoación y tramitación de expedientes disciplinarios por los mismos hechos, en tanto no recaiga sentencia firme.',b:'Impedirá la incoación y tramitación de expedientes disciplinarios o gubernativos por los mismos hechos, salvo en los casos expresamente previstos en la ley.',c:'No impedirá la incoación y tramitación de expedientes disciplinarios o gubernativos por los mismos hechos.',d:'No impedirá la incoación y tramitación de expedientes disciplinarios o gubernativos por los mismos hechos, salvo en aquellos casos expresamente previstos en la ley.'}, correct:'c', why:{c:'El art. 8.1 LO 2/1986 establece que la incoación de un procedimiento penal no impedirá la tramitación de expedientes disciplinarios o gubernativos por los mismos hechos, aunque la resolución definitiva del expediente deberá esperar a la firmeza de la sentencia.'}},
{n:67, q:'Según la Ley Orgánica 2/1986, en el supuesto de que se instruya un procedimiento disciplinario por hechos cometidos por miembros de las FFCCSS, que sean objeto de enjuiciamiento penal...', o:{a:'La resolución definitiva del expediente solo podrá producirse cuando la sentencia recaída en el ámbito penal sea firme.',b:'La declaración de hechos probados por la autoridad judicial no vinculará a la administración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 8.1 LO 2/1986 establece que cuando los hechos sean objeto de enjuiciamiento penal, la resolución definitiva del expediente disciplinario solo podrá producirse cuando la sentencia penal sea firme.'}},
{n:68, q:'Según la Ley Orgánica 2/1986, las medidas cautelares adoptadas en un procedimiento disciplinario por hechos cometidos por miembros de las FFCCSS, que sean objeto de enjuiciamiento penal...', o:{a:'Podrán prolongarse hasta que recaiga resolución definitiva en el proceso penal, salvo en lo que se refiere a la suspensión de funciones en que se estará a lo dispuesto en la legislación general de funcionarios.',b:'Podrán prolongarse hasta que recaiga resolución definitiva en el proceso penal, salvo en lo que se refiere a la privación de libertad en que se estará a lo dispuesto en la legislación general de funcionarios.',c:'Podrán prolongarse hasta que recaiga resolución definitiva en el proceso penal, salvo en lo que se refiere a la suspensión de sueldo en que se estará a lo dispuesto en la legislación general de funcionarios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'c', why:{c:'El art. 8.1 LO 2/1986 establece que las medidas cautelares podrán prolongarse hasta la resolución definitiva penal, salvo en lo relativo a la suspensión de sueldo, donde se aplica la legislación general de funcionarios.'}},
{n:69, q:'En la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad "De las Policías Locales" es el nombre que recibe...', o:{a:'El capítulo III de su Título V.',b:'Su Título V.',c:'El capítulo IV de su Título IV.',d:'Su Título IV.'}, correct:'b', why:{b:'El Título V de la LO 2/1986 se denomina "De las Policías Locales" y regula la naturaleza, funciones y régimen de los cuerpos de policía dependientes de las Corporaciones Locales.'}},
{n:70, q:'El Título V de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad denominado "De las Policías Locales" comprende los artículos...', o:{a:'50 a 54.',b:'50 a 53.',c:'51 a 54.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El Título V de la LO 2/1986 comprende los arts. 51 a 54, que regulan la creación de los cuerpos, sus funciones, la actuación fuera del término municipal y las Juntas Locales de Seguridad.'}},
{n:71, q:'Según el artículo 51 de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, los municipios...', o:{a:'Están obligados a crear cuerpos de policía local propios.',b:'Pueden crear cuerpos de policía local propios.',c:'No pueden crear cuerpos de policía local propios, salvo en los casos establecidos en esta Ley.',d:'Ninguna de las respuestas anteriores es correcta'}, correct:'b', why:{b:'El art. 51 LO 2/1986 establece que los municipios "podrán" (facultad, no obligación) crear cuerpos de policía local propios, sujetándose a los principios básicos de actuación de la Ley.'}},
{n:72, q:'Los municipios pueden crear cuerpos de policía propios, de acuerdo con lo previsto en...', o:{a:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad.',b:'La Ley de Bases de Régimen Local.',c:'La legislación autonómica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La creación de cuerpos de Policía Local se regula en la LO 2/1986, en la Ley de Bases de Régimen Local y en la legislación autonómica respectiva, debiendo cumplirse todos estos marcos normativos.'}},
{n:73, q:'Las misiones asignadas a la Policía Local en su condición de Cuerpo de Seguridad, conforme a lo previsto en el artículo 104.1 de la Constitución Española, son:', o:{a:'Proteger el libre ejercicio de los derechos y libertades, y garantizar la seguridad ciudadana.',b:'Mantener la seguridad pública, ayudando y colaborando con los ciudadanos y demás poderes públicos, y en especial con aquellos colectivos necesitados de especial protección.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 104.1 CE asigna a las FFCCSS, incluida la Policía Local, la misión de proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana. La opción a) recoge exactamente esta misión.'}},
{n:74, q:'Según el artículo 51 de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, en los municipios donde no exista Policía Local, los cometidos de ésta serán ejercidos por...', o:{a:'Alguaciles.',b:'Vigilantes.',c:'Agentes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 51.2 LO 2/1986 establece que en los municipios donde no exista Policía Local sus cometidos podrán ser ejercidos por alguaciles, vigilantes o agentes dependientes de la Corporación Local.'}},
{n:75, q:'Según la Ley Orgánica 2/1986, en los municipios donde no exista Policía Local, sus cometidos serán ejercidos:', o:{a:'Por los miembros de las Fuerzas y Cuerpos de Seguridad del Estado.',b:'Por el personal que desempeñe funciones de custodia y vigilancia de bienes, servicios e instalaciones.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 51.2 LO 2/1986 establece que en los municipios donde no exista Policía Local sus cometidos serán ejercidos por personal que desempeñe funciones de custodia y vigilancia de bienes, servicios e instalaciones dependiente de la Corporación Local.'}},
{n:76, q:'Las Policías Locales podrán actuar fuera de su término municipal:', o:{a:'Cuando ejerzan funciones de protección de autoridades, siempre que cuenten con autorización del Ministerio del Interior o Comunidad Autónoma, dependiendo del ámbito territorial donde las realicen.',b:'En situaciones de emergencia y previo requerimiento de las autoridades competentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 51.3 LO 2/1986 permite a las Policías Locales actuar fuera de su término municipal tanto en funciones de protección de autoridades con autorización del Ministerio del Interior o CCAA (opción a) como en situaciones de emergencia previo requerimiento (opción b); ambas son correctas.'}},
{n:77, q:'Según el artículo 52 de la Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, los Cuerpos de Policía Local...', o:{a:'Son institutos de naturaleza civil.',b:'Son institutos armados de naturaleza civil.',c:'Tienen una estructura y organización disciplinada.',d:'Tienen una estructura y organización representadas en distintos niveles.'}, correct:'b', why:{b:'El art. 52 LO 2/1986 define los Cuerpos de Policía Local como institutos armados de naturaleza civil, con estructura y organización jerarquizada.'}},
{n:78, q:'Según el artículo 52 de la Ley Orgánica 2/1986, en lo que respecta al ejercicio de los derechos sindicales de los integrantes de los Cuerpos de Policía Local...', o:{a:'Les será de aplicación la ley que se dicte en cumplimiento de lo establecido en la disposición adicional tercera, apartado 2, de la Ley Orgánica 11/1985 de Libertad Sindical.',b:'Les será de aplicación la ley que se dicte en cumplimiento de lo establecido en la disposición adicional segunda, apartado 2, de la Ley Orgánica 11/1985 de Libertad Sindical.',c:'Les será de aplicación la ley que se dicte en cumplimiento de lo establecido en la disposición adicional primera, apartado 2, de la Ley Orgánica 11/1985 de Libertad Sindical.',d:'Les será de aplicación la ley que se dicte en cumplimiento de lo establecido en la disposición adicional tercera, apartado 3, de la Ley Orgánica 11/1985 de Libertad Sindical.'}, correct:'b', why:{b:'El art. 52.2 LO 2/1986 remite a la ley dictada en cumplimiento de la disposición adicional segunda, apartado 2, de la LO 11/1985 de Libertad Sindical para regular los derechos sindicales de las Policías Locales.'}},
{n:79, q:'Según el artículo 52.3 de la Ley Orgánica 2/1986, en el ejercicio de sus funciones, los miembros de los Cuerpos de Policía Local deberán vestir el uniforme reglamentario...', o:{a:'Salvo en los casos excepcionales que autorice una ley orgánica.',b:'Salvo en los casos excepcionales que reglamentariamente se determinen.',c:'Salvo en los casos excepcionales que autoricen las Juntas Locales de Seguridad.',d:'Salvo en los casos excepcionales que autorice el Subdelegado del Gobierno respectivo.'}, correct:'d', why:{d:'El art. 52.3 LO 2/1986 establece que los Policías Locales vestirán el uniforme reglamentario salvo en los casos excepcionales que autorice el Subdelegado del Gobierno respectivo.'}},
{n:80, q:'En cuanto a su régimen estatutario, los Cuerpos de Policía Local se rigen por los principios generales establecidos al respecto en la Ley Orgánica 2/1986, de FFCCSS, con la adecuación que exijan:', o:{a:'La dependencia de la Administración correspondiente.',b:'Las disposiciones dictadas al respecto por las Comunidades Autónomas y los Reglamentos específicos para cada Cuerpo.',c:'Las normas dictadas por los correspondientes Ayuntamientos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 52.1 LO 2/1986 establece que el régimen estatutario de las Policías Locales se regirá por los principios de la Ley con las adecuaciones derivadas de la dependencia de la Administración local, las normas autonómicas y los reglamentos específicos de cada cuerpo.'}},
{n:81, q:'Según el artículo 53 de la Ley Orgánica 2/1986, es una de las funciones atribuidas a la Policía Local:', o:{a:'Proteger a las autoridades de las Corporaciones Locales.',b:'La vigilancia y custodia de todos los edificios e instalaciones existentes en su término municipal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 53.1.a) LO 2/1986 atribuye a la Policía Local la función de proteger a las autoridades de las Corporaciones Locales y vigilar o custodiar sus edificios e instalaciones; solo la opción a) es correcta por sí sola.'}},
{n:82, q:'Según el artículo 53 de la Ley Orgánica 2/1986, es una función atribuida a la Policía Local...', o:{a:'Ordenar, señalizar y dirigir el tráfico en el casco urbano de acuerdo con lo establecido en las normas de circulación.',b:'Instruir atestados por accidentes de circulación dentro del casco urbano.',c:'Policía administrativa, en lo relativo a las ordenanzas, bandos y demás disposiciones municipales, dentro del ámbito de su competencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 53 LO 2/1986 atribuye a la Policía Local todas estas funciones: ordenar y dirigir el tráfico (art. 53.1.b), instruir atestados por accidentes urbanos (art. 53.1.c) y ejercer la policía administrativa municipal (art. 53.1.d).'}},
{n:83, q:'Según el artículo 53 de la Ley Orgánica 2/1986, no es función atribuida a la Policía Local...', o:{a:'La participación en las funciones de Policía Judicial tal como se determina en el art. 29.2 de la Ley Orgánica de Fuerzas y Cuerpos de Seguridad.',b:'La prestación de auxilio en casos de accidente, catástrofe o calamidad pública, participando en la forma prevista en las Leyes, en la ejecución de los planes de protección civil.',c:'Efectuar diligencias de investigación y cuantas actuaciones tiendan a evitar la comisión de actos delictivos en el marco de colaboración establecido en las Juntas de Policía Judicial.',d:'Vigilar los espacios públicos.'}, correct:'c', why:{c:'La Policía Local no tiene atribuida la función de efectuar diligencias de investigación en el marco de las Juntas de Policía Judicial (que no existen con ese nombre). El art. 53 LO 2/1986 le atribuye colaborar en el marco de las Juntas Locales de Seguridad, no de Policía Judicial.'}},
{n:84, q:'Es una función atribuida a la Policía Local:', o:{a:'Colaborar con las FFCCSS del Estado y con la Policía de las CCAA en la protección de las manifestaciones, cuando sean requeridos para ello.',b:'Colaborar con las FFCCSS del Estado y con la Policía de las CCAA en el mantenimiento del orden en grandes concentraciones humanas, cuando sean requeridos para ello.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 53.1.h) LO 2/1986 atribuye a la Policía Local colaborar con las FFCCSS del Estado y policías autonómicas tanto en la protección de manifestaciones como en el mantenimiento del orden en grandes concentraciones, cuando sea requerida.'}},
{n:85, q:'Es una función atribuida a la Policía Local:', o:{a:'Proteger a las autoridades de las Corporaciones Locales y vigilar o custodiar sus edificios e instalaciones.',b:'Ordenar, señalizar y dirigir el tráfico en el casco urbano.',c:'Instruir atestados por accidente de circulación dentro del casco urbano.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 53 LO 2/1986 atribuye a la Policía Local todas estas funciones: proteger autoridades locales (art. 53.1.a), dirigir el tráfico urbano (art. 53.1.b) e instruir atestados por accidentes en el casco urbano (art. 53.1.c).'}},
{n:86, q:'Es una función atribuida a la Policía Local:', o:{a:'La de Policía Administrativa, en lo relativo a ordenanzas, bandos y demás disposiciones municipales, autonómicas o nacionales.',b:'Participar en las funciones de policía judicial en la forma prevista en el art. 29.2 de la Ley Orgánica de Fuerzas y Cuerpos de Seguridad.',c:'La prestación de auxilio en los casos de accidente, catástrofe o calamidad, salvo que los Cuerpos de Seguridad del Estado ya se hallaren prestando dicho auxilio.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 53.1.f) LO 2/1986 atribuye expresamente a la Policía Local la función de participar en las funciones de Policía Judicial conforme a lo previsto en el art. 29.2 de la misma Ley.'}},
{n:87, q:'Es una de las funciones atribuidas a la Policía Local:', o:{a:'La de efectuar diligencias de prevención y cuantas actuaciones tiendan a evitar la comisión de actos delictivos en el marco de colaboración establecido en las Juntas de Seguridad.',b:'Vigilar los espacios públicos y colaborar con las FFCCSS del Estado y con la Policía de las CCAA, en la protección de las manifestaciones y el mantenimiento del orden en grandes concentraciones humanas, cuando sean requeridos para ello.',c:'Cooperar en la resolución de conflictos privados cuando sean requeridos para ello.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 53 LO 2/1986 atribuye a la Policía Local las tres funciones: diligencias de prevención delictiva (art. 53.1.f), vigilancia de espacios públicos y colaboración en manifestaciones (art. 53.1.h), y cooperación en conflictos privados (art. 53.1.i).'}},
{n:88, q:'De las siguientes funciones, señale aquella que, una vez realizada por la Policía Local, debe ser comunicada a las Fuerzas y Cuerpos de Seguridad del Estado competentes.', o:{a:'Cooperar en la resolución de conflictos privados.',b:'Efectuar diligencias de prevención y demás actuaciones encaminadas a evitar la comisión de actos delictivos.',c:'Participar en las funciones de Policía Judicial conforme a lo previsto en el art. 29.2 de la LO de Fuerzas y Cuerpos de Seguridad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 53.1.f) LO 2/1986 establece que las diligencias de prevención e intervenciones para evitar la comisión de delitos realizadas por la Policía Local deben comunicarse a las FFCCSS del Estado competentes.'}},
{n:89, q:'De las siguientes funciones, señale aquella que, una vez realizada por la Policía Local, debe ser comunicada a las Fuerzas y Cuerpos de Seguridad del Estado competentes.', o:{a:'Ordenar, señalizar y dirigir el tráfico en el casco urbano, de acuerdo con lo establecido en las normas de circulación.',b:'Instruir atestados por accidente de circulación dentro del casco urbano.',c:'Participar en las funciones de Policía Judicial en la forma establecida en el art. 29.2 de la LO de Fuerzas y Cuerpos de Seguridad.',d:'Cooperar en la regulación de conflictos privados cuando sean requeridos para ello.'}, correct:'b', why:{b:'El art. 53.1.c) LO 2/1986 establece que los atestados instruidos por la Policía Local por accidentes de circulación en el casco urbano deben comunicarse a las FFCCSS del Estado competentes.'}},
{n:90, q:'Según el artículo 53.3 de la Ley Orgánica 2/1986, las funciones de ordenar, señalizar y dirigir el tráfico en el casco urbano, de acuerdo con lo establecido en las normas de circulación...', o:{a:'Deben ser realizadas de manera exclusiva por funcionarios integrados en los Cuerpos de Policía Local.',b:'Deben ser realizadas por funcionarios integrados en los Cuerpos de Policía Local, salvo cuando se produzcan alteraciones graves de la seguridad ciudadana, en cuyo caso serán realizadas por personal de las FFCCSS del Estado.',c:'Pueden ser realizadas por otros funcionarios de la corporación que no pertenezcan a la Policía Local, en determinados supuestos.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'c', why:{c:'El art. 53.3 LO 2/1986 prevé que en determinados supuestos las funciones de ordenación del tráfico puedan ser ejercidas por otros funcionarios de la Corporación que no pertenezcan a la Policía Local.'}},
{n:91, q:'Con respecto a la previsión del artículo 53.3 de la Ley Orgánica 2/1986, en cuanto a la realización de las funciones de ordenación, señalización y dirección del tráfico en el casco urbano por parte de funcionarios de la corporación municipal que no tengan la condición de policía local, indique cuál de las siguientes expresiones no es correcta:', o:{a:'Solo pueden darse estos supuestos en municipios de gran población y en ciudades con Estatuto de Autonomía.',b:'Estos funcionarios no podrán integrarse en las Fuerzas y Cuerpos de Seguridad.',c:'En el ejercicio de sus funciones no son agentes de la autoridad, sino auxiliares de ésta.',d:'La creación de estos funcionarios no puede comportar ningún incremento en el número de efectivos, ni en el coste de personal de la corporación respectiva.'}, correct:'a', why:{a:'El art. 53.3 LO 2/1986 no restringe esta posibilidad a municipios de gran población o ciudades con Estatuto de Autonomía; puede darse en cualquier municipio bajo las condiciones legales establecidas. Por tanto, la opción a) es la que NO es correcta.'}},
{n:92, q:'Con respecto a la previsión del artículo 53.3 de la Ley Orgánica 2/1986, en cuanto a la realización de las funciones de ordenación, señalización y dirección del tráfico en el casco urbano por parte de funcionarios de la corporación municipal que no tengan la condición de policía local, indique cuál de las siguientes expresiones no es correcta:', o:{a:'Estos funcionarios tendrán la consideración de agentes de la autoridad.',b:'Estarán subordinados a los miembros de los respectivos Cuerpos de Policía Local.',c:'Solo pueden darse estos supuestos en municipios de gran población y en ciudades con estatuto de autonomía.',d:'La asignación de estas funciones al personal indicado debe llevarse a cabo por el Pleno de la Corporación, o por los respectivos Gobiernos en el caso de las ciudades con estatuto de autonómica.'}, correct:'d', why:{d:'El art. 53.3 LO 2/1986 no atribuye al Pleno ni a los Gobiernos autonómicos la asignación de estas funciones de la forma descrita. Esta afirmación no es correcta conforme a la literalidad del precepto.'}},
{n:93, q:'Según el artículo 54 de la Ley Orgánica 2/1986, podrá constituirse una Junta Local de Seguridad...', o:{a:'Únicamente en aquellos municipios en que lo autorice la Subdelegación del Gobierno.',b:'Únicamente en municipios que tengan cuerpo de policía propio.',c:'Únicamente en municipios de gran población.',d:'Únicamente en municipios cabeza de partido judicial.'}, correct:'b', why:{b:'El art. 54.1 LO 2/1986 establece que podrá constituirse una Junta Local de Seguridad en los municipios que cuenten con cuerpo de policía propio, para establecer las formas y procedimientos de colaboración entre las FFCCSS en ese ámbito.'}},
{n:94, q:'Según el artículo 54 de la Ley Orgánica 2/1986, la Junta Local de Seguridad será el órgano competente para...', o:{a:'Establecer las formas y procedimientos de colaboración entre los miembros de las FFCCSS en su ámbito territorial.',b:'Establecer las formas y procedimientos de colaboración entre los miembros de las FFCCSS y la Administración de Justicia, en su ámbito territorial.',c:'Establecer las formas y procedimientos de colaboración entre los miembros de las FFCCSS del Estado, en su ámbito territorial.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 54.1 LO 2/1986 establece que la Junta Local de Seguridad es el órgano competente para establecer las formas y procedimientos de colaboración entre los miembros de las FFCCSS en el ámbito territorial del municipio.'}},
{n:95, q:'Según el artículo 54 de la Ley Orgánica 2/1986, la presidencia de la Junta Local de Seguridad...', o:{a:'Corresponderá al Alcalde, en todo caso.',b:'Corresponderá al Subdelegado del Gobierno, en todo caso.',c:'Corresponderá al Alcalde, salvo que concurriera a sus sesiones el Subdelegado del Gobierno de la provincia, en cuyo caso, la presidencia será compartida con éste.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art. 54.2 LO 2/1986 establece que la presidencia de la Junta Local de Seguridad corresponde al Alcalde, salvo cuando asista el Subdelegado del Gobierno de la provincia, en cuyo caso la presidencia será compartida entre ambos.'}},
{n:96, q:'Las Juntas Locales de Seguridad están reguladas mediante:', o:{a:'El Real Decreto 87/2010',b:'El Real Decreto 1087/2010.',c:'El Real Decreto 108/2010.',d:'El Real Decreto 1008/2010.'}, correct:'b', why:{b:'Las Juntas Locales de Seguridad están reguladas por el Real Decreto 1087/2010, de 3 de septiembre, que establece los requisitos y procedimiento para su constitución y funcionamiento.'}},
{n:97, q:'Entre los integrantes de las Juntas Locales de Seguridad, previstos en el artículo 5 del Real Decreto 1087/2010, no se halla/n...', o:{a:'Un representante de la Administración Autonómica',b:'El Jefe o Jefes de las FFCCSS del Estado que ejerzan sus funciones en el ámbito territorial del municipio.',c:'El Jefe de la Policía Local del Municipio.',d:'El Alcalde del Municipio.'}, correct:'c', why:{c:'El art. 5 RD 1087/2010 no incluye al Jefe de la Policía Local del Municipio como integrante de pleno derecho de la Junta Local de Seguridad; sí figuran el Alcalde, el Subdelegado del Gobierno, los jefes de las FFCCSS del Estado y el representante autonómico.'}},
{n:98, q:'Las Secretarías de las Juntas Locales de Seguridad serán desempeñadas:', o:{a:'Por el Alcalde o persona en quien delegue.',b:'Por el miembro de la Junta que haya sido designado mediante votación producida en su seno.',c:'Alternativamente, por periodos de un año, por el Secretario del Ayuntamiento o Secretario de la Delegación o Subdelegación del Gobierno, o de la Administración Autonómica.',d:'Alternativamente, por periodos de un año, por un funcionario del Ayuntamiento designado por el Alcalde, o de la Administración del Estado, designado por el Delegado o Subdelegado del Gobierno.'}, correct:'d', why:{d:'El art. 7 RD 1087/2010 establece que la Secretaría de la Junta Local de Seguridad se desempeñará alternativamente, por periodos de un año, por un funcionario del Ayuntamiento designado por el Alcalde y un funcionario de la Administración del Estado designado por el Delegado/Subdelegado del Gobierno.'}},
];
